for k, v in sorted(exps.items()):
    if 'sim_sweep' in k:
        metrics = v.get('metrics', {})
        spec = v.get('spec', {})
        print(f'{k}: status={v[\"status\"]}, conclusion={v.get(\"conclusion\",\"\")}')
